match router.on_capture(ev, now) {
  Disposition::Local => inject_local(ev),
  Disposition::Forward(peer) => enqueue(peer, ev),
  Disposition::Refused => { /* 保持本机状态 */ }
}

match event.delivery {
  Delivery::Reliable => uni_stream(N1).send(event),
  Delivery::Datagram => datagram(I0).send(event),
}
